(function () {
  var MIN = 3, MAX = 50, DEF = 25;
  function cl(v) {
    if (v === undefined || v === null) return '';
    var s = String(v);
    if (s.indexOf('$.') === 0) return '';
    if (s === 'undefined' || s === 'null' || s === '[]' || s === '{}') return '';
    return s;
  }
  var raw = cl(q).trim();
  var tokens = raw.toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/^ +| +$/g, '').split(' ');
  var t2 = [];
  for (var i = 0; i < tokens.length; i++) { if (tokens[i].length > 0) t2.push(tokens[i]); }
  tokens = t2;
  var lim = parseInt(cl(limit), 10);
  if (!(lim > 0)) lim = DEF;
  if (lim > MAX) lim = MAX;
  var off = parseInt(cl(offset), 10);
  if (!(off > 0)) off = 0;
  var FIELDS = {
    itpi: 'itpi_eligibility', itl: 'itpi_eligibility', it: 'itpi_eligibility',
    itcl: 'itpi_eligibility', itcl01: 'itpi_eligibility',
    ah: 'ah_eligibility', allied_health: 'ah_eligibility', ahcl: 'ah_eligibility',
    gp: 'gp_eligibility', general_property: 'gp_eligibility', gp01: 'gp_eligibility'
  };
  var key = cl(product).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+/, '').replace(/_+$/, '');
  var field = FIELDS[key] || '';
  var wantedRaw = cl(eligibility);
  if (wantedRaw === '') wantedRaw = 'yes,refer';
  var parts = wantedRaw.toLowerCase().split(',');
  var wanted = [];
  for (var j = 0; j < parts.length; j++) {
    var w = parts[j].replace(/^ +| +$/g, '');
    if (w === 'yes' || w === 'no' || w === 'refer') { wanted.push(w); }
  }
  if (wanted.length === 0) wanted = ['yes', 'refer'];
  var tooShort = tokens.length > 0 && raw.length < MIN;
  var ok = (tokens.length > 0 && raw.length >= MIN) || (tokens.length === 0 && field !== '');
  var conditions = [{ field: 'occupation_active', keyword: 'true' }];
  for (var k = 0; k < tokens.length; k++) {
    conditions.push({ field: 'occupation_label', prefix: tokens[k] });
  }
  if (field !== '') {
    var group = [];
    for (var m = 0; m < wanted.length; m++) { group.push({ field: field, keyword: wanted[m] }); }
    conditions.push({ operator: 'or', conditions: group });
  }
  var fetchLim = lim;
  if (!ok) {
    conditions = [{ field: 'occupation_code', keyword: '__no_query__' }];
    fetchLim = 1;
  }
  return {
    ok: ok,
    reason: ok ? 'query' : (tooShort ? 'below_min_chars' : 'no_criteria'),
    min_chars: MIN,
    max_limit: MAX,
    limit: String(lim),
    fetch_limit: String(fetchLim),
    offset: String(off),
    sort_by: 'occupation_label',
    tokens: tokens,
    product: key,
    product_field: field,
    eligibility: wanted,
    filter: JSON.stringify({ conditions: conditions })
  };
})()

(function () {
  var src = (fetched && typeof fetched === 'object' && fetched.data && typeof fetched.data === 'object') ? fetched.data : null;
  var rows = (src && Object.prototype.toString.call(src.results) === '[object Array]') ? src.results : [];
  var total = (src && typeof src.total_hits === 'number') ? src.total_hits : 0;
  var p = (prep && typeof prep === 'object') ? prep : {};
  var lim = parseInt(p.limit, 10); if (!(lim > 0)) lim = 25;
  var off = parseInt(p.offset, 10); if (!(off > 0)) off = 0;
  var options = [];
  for (var i = 0; i < rows.length; i++) {
    var d = (rows[i] && rows[i].data) ? rows[i].data : {};
    var flags = [];
    if (d.itpi_eligibility) flags.push('ITPI ' + d.itpi_eligibility);
    if (d.ah_eligibility) flags.push('Allied Health ' + d.ah_eligibility);
    if (d.gp_eligibility) flags.push('General Property ' + d.gp_eligibility);
    options.push({
      value: d.occupation_code === undefined || d.occupation_code === null ? '' : String(d.occupation_code),
      text: d.occupation_label === undefined || d.occupation_label === null ? '' : String(d.occupation_label),
