      ah_default_limit: d.ah_default_limit,
      gp_eligibility: d.gp_eligibility,
      gp_question_set: d.gp_question_set,
      gp_wording: d.gp_wording,
      gp_min_premium: d.gp_min_premium,
      gp_min_excess: d.gp_min_excess,
      gp_default_limit: d.gp_default_limit,
      data: d
    });
  }
  return {
    options: options,
    total: total,
    count: options.length,
    limit: lim,
    offset: off,
    has_more: (off + options.length) < total,
    next_offset: ((off + options.length) < total) ? (off + options.length) : null,
    reason: p.reason || '',
    tokens: p.tokens || [],
    product: p.product || '',
    searched: p.reason === 'query'
  };
})()
